def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_c = opp.count('C')
    opp_rate = opp_c / n

    # Defect on the very last round.
    if n >= 100:
        return 'D'

    # Identify likely always-cooperative opponent: exploit but stay mostly cooperative,
    # and lock in mutual cooperation near the end (no point exploiting if it risks
    # spoiling a long cooperative streak).
    if opp_rate >= 0.95 and n >= 8:
        recent = opp[-10:]
        if recent.count('D') == 0:
            if n >= 90:
                return 'C'
            # occasional probe to see if they punish; otherwise cooperate
            if n % 9 == 0 and rng.random() < 0.5:
                return 'D'
            return 'C'

    # Identify likely always-defector: defend.
    if opp_rate <= 0.1 and n >= 8:
        if n % 7 == 0 and rng.random() < 0.2:
            return 'C'
        return 'D'

    last_me, last_opp = history[-1]

    # Count consecutive DD pairs to break defection spirals.
    dd_run = 0
    for i in range(n - 1, -1, -1):
        if me[i] == 'D' and opp[i] == 'D':
            dd_run += 1
        else:
            break

    # Count consecutive CD pairs (I cooperated, opp defected).
    cd_run = 0
    for i in range(n - 1, -1, -1):
        if me[i] == 'C' and opp[i] == 'D':
            cd_run += 1
        else:
            break

    # Count consecutive DC pairs (I defected, opp cooperated).
    dc_run = 0
    for i in range(n - 1, -1, -1):
        if me[i] == 'D' and opp[i] == 'C':
            dc_run += 1
        else:
            break

    # Count recent cooperation.
    recent_opp = opp[-8:]
    recent_c = recent_opp.count('C')
    recent_d = len(recent_opp) - recent_c

    # Late-game: protect long cooperation streaks; otherwise defect opportunistically.
    if n >= 90:
        if recent_c >= 6:
            return 'C'
        if recent_d >= 5:
            return 'D'
        if last_opp == 'D':
            return 'D'
        return 'C'

    # If opponent has been defecting a lot recently, defend and punish.
    if recent_d >= 6:
        return 'D'

    # If both defecting in a long stretch, try to break out with a cooperation.
    if dd_run >= 2:
        if dd_run >= 5:
            return 'C'
        if rng.random() < 0.4:
            return 'C'
        return 'D'

    # Opponent just defected while I cooperated: retaliate once, then consider forgiveness.
    if last_opp == 'D' and last_me == 'C':
        if cd_run >= 3:
            return 'D'
        # single retaliation
        return 'D'

    # I defected, opponent cooperated: return to cooperation to avoid feud.
    if last_me == 'D' and last_opp == 'C':
        if dc_run >= 3:
            # Repeated exploitation - the opponent keeps cooperating, keep exploiting softly.
            if n < 85 and rng.random() < 0.4:
                return 'D'
            return 'C'
        return 'C'

    # Both cooperated last: preserve mutual cooperation.
    if last_me == 'C' and last_opp == 'C':
        # Occasional mild probe if opponent has been very cooperative and it's still safe.
        if opp_rate >= 0.85 and n >= 25 and n < 70 and n % 12 == 0:
            if rng.random() < 0.3:
                return 'D'
        return 'C'

    # Default: cooperate.
    return 'C'
